# Writes the upstream fix (projects/mupdf/arvo_5912/patch.diff @ 8365b29) to
# /output/fix.patch and the ground-truth PoC to /output/poc.bin.
set -euo pipefail

mkdir -p /output
base64 -d > /output/fix.patch <<'B64'
